[...document.querySelectorAll(".detail-item")].forEach(e=>{const t=e.querySelector("button"),i=e.querySelector(".detail-item__panel");t.addEventListener("click",()=>{const r="true"!==t.getAttribute("aria-expanded");e.classList.toggle("is-open",r),t.setAttribute("aria-expanded",String(r)),i.setAttribute("aria-hidden",String(!r))})});